<script lang="ts">export let open=false;export let title='Confirmar acción';export let message='';export let confirmLabel='Confirmar';export let busy=false;export let onconfirm:()=>void=()=>{};export let oncancel:()=>void=()=>{};let dialog:HTMLDialogElement;$:if(dialog){if(open&&!dialog.open)dialog.showModal();if(!open&&dialog.open)dialog.close()}function close(){if(!busy)oncancel()}</script>
<dialog bind:this={dialog} on:cancel={(event)=>{event.preventDefault();close()}} on:close={()=>{if(open&&!busy)oncancel()}}><h2>{title}</h2><p>{message}</p><div><button class="button-secondary" type="button" disabled={busy} on:click={close}>Cancelar</button><button class="button-danger" type="button" disabled={busy} on:click={onconfirm}>{busy?'Guardando…':confirmLabel}</button></div></dialog>
<style>h2{margin:0;font:600 1.75rem/1.1 var(--display)}p{margin:1rem 0 1.5rem}div{display:flex;justify-content:flex-end;gap:.75rem;flex-wrap:wrap}</style>
